import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position
  const sp = config.scenePosition || {};
  group.position.set(sp.x ?? 0, sp.y ?? 0, sp.z ?? 0);

  // Apply rotation (XYZ order)
  if (sp.rotationXYZ) {
    group.rotation.order = 'XYZ';
    group.rotation.x = sp.rotationXYZ[0] ?? 0;
    group.rotation.y = sp.rotationXYZ[1] ?? 0;
    group.rotation.z = sp.rotationXYZ[2] ?? 0;
  }

  // Apply scale
  if (sp.scaleXYZ) {
    group.scale.set(sp.scaleXYZ[0] ?? 1, sp.scaleXYZ[1] ?? 1, sp.scaleXYZ[2] ?? 1);
  }

  // Create plane geometry (1×1 unit)
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture from imageUrl (synchronous, cached)
  const textureMap = ctx.textureLoader.load(config.imageUrl);

  // Create material (MeshBasicMaterial for static, non-lit surface)
  const material = new THREE.MeshBasicMaterial({
    map: textureMap,
    toneMapped: false,
  });

  // Create mesh and add to group
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  // Initialize handlers (no interactions on this card)
  group.userData.handlers = {};

  return group;
}
